  "gorsel": "<table class=\"tablo\"><tr><th>Ev</th><th>Önceki ay (kWh)</th><th>Bu ay (kWh)</th></tr><tr><td>K</td><td>120</td><td>90</td></tr><tr><td>L</td><td>300</td><td>240</td></tr><tr><td>M</td><td>200</td><td>160</td></tr><tr><td>N</td><td>60</td><td>54</td></tr></table>",
